mapper.update:
update member_funding_wallet wallet
set wallet.balance = wallet.balance - #{amount},
wallet.frozen_balance = wallet.frozen_balance + #{amount}
where wallet.id = #{walletId} and wallet.balance >= #{amount}

update member_funding_wallet wallet
set wallet.balance = wallet.balance + #{amount},
wallet.frozen_balance = wallet.frozen_balance - #{amount}
where wallet.id = #{walletId} and wallet.frozen_balance >= #{amount}
